int f( int x )
{
    if( x == 0 )
        return 0;
    else
        return 2 * f( x - 1 ) + x * x;
}

int bad( int n )
{
    if( n == 0 )
        return 0;
    else
        return bad( n / 3 + 1 ) + n - 1;
}

