/**
 * 一个模拟整数内存单元的类.
 */
class IntCell
{
    public:
        /**
         * 构建 IntCell对象.
         * 初始值为0.
         */
        IntCell( )
        { storedValue = 0; }

        /**
         * 构建 IntCell对象.
         * 初始值为 initialValue.
         */
        IntCell( int initialValue )
        { storedValue = initialValue; }

        /**
         * 返回所存储的值.
         */
        int read( )
        { return storedValue; }

        /**
         * 将所存储的值改为x.
         */
        void write( int x )
        { storedValue = x; }

    private:
        int storedValue;
};

/**
 * 一个模拟整数内存单元的类.
